local BreadLameMaker = {}
local PRODUCTS = {
    iron_breadlame = { name = "Železni rezilo za kruh", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni rezilo za kruh za pekarno." },
    bronze_breadlame = { name = "Bronast rezilo za kruh", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast rezilo za kruh za pekarno." },
    silver_breadlame = { name = "Srebrn rezilo za kruh", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn rezilo za kruh za pekarno." },
    gilded_breadlame = { name = "Pozlačen rezilo za kruh", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen rezilo za kruh za pekarno." },
    jewel_set_breadlame = { name = "Draguljast rezilo za kruh", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast rezilo za kruh za pekarno." },
    royal_sovereign_breadlame = { name = "Kraljevski suveren rezilo za kruh", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren rezilo za kruh z biseri za krono." },
}
local BUILDINGS = {
    breadlame_workshop = { name = "Breadlame delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    breadlame_house = { name = "Breadlame hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_breadlame_atelier = { name = "Mojstrski breadlame atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_breadlame_palace = { name = "Suverena breadlame palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BreadLameMaker.ironStock = 16; BreadLameMaker.bronzeStock = 14; BreadLameMaker.woodStock = 10; BreadLameMaker.leatherStock = 8; BreadLameMaker.silverStock = 8; BreadLameMaker.goldStock = 6; BreadLameMaker.jewelStock = 4; BreadLameMaker.pearlStock = 4
BreadLameMaker.productStock = {}; BreadLameMaker.buildings = {}; BreadLameMaker.maker = nil; BreadLameMaker.activeMaking = {}; BreadLameMaker.totalProducts = 0; BreadLameMaker.dayTimer = 0
function BreadLameMaker.init() BreadLameMaker.ironStock=16; BreadLameMaker.bronzeStock=14; BreadLameMaker.woodStock=10; BreadLameMaker.leatherStock=8; BreadLameMaker.silverStock=8; BreadLameMaker.goldStock=6; BreadLameMaker.jewelStock=4; BreadLameMaker.pearlStock=4; BreadLameMaker.productStock={}; BreadLameMaker.buildings={}; BreadLameMaker.maker=nil; BreadLameMaker.activeMaking={}; BreadLameMaker.totalProducts=0; BreadLameMaker.dayTimer=0; print("[BreadLameMaker] Royal Bread Lame Maker System initialized (6 products, 4 buildings)") end
function BreadLameMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BreadLameMaker.maker={name=n or ("Rezilec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezilec najet: %s (spretnost: %d)",BreadLameMaker.maker.name,s),"success") end; return true end
function BreadLameMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BreadLameMaker.build(id) local ok,e=BreadLameMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BreadLameMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BreadLameMaker.getQualityBonus() local b=0; for _,bd in ipairs(BreadLameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BreadLameMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BreadLameMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BreadLameMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BreadLameMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BreadLameMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BreadLameMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BreadLameMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BreadLameMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BreadLameMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BreadLameMaker.buildings==0 then return false,"Potrebna rezilna delavnica" end; if not BreadLameMaker.maker then return false,"Potreben rezilec" end; return true end
function BreadLameMaker.make(pt,qty) qty=qty or 1; local ok,e=BreadLameMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BreadLameMaker.ironStock=BreadLameMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BreadLameMaker.bronzeStock=BreadLameMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BreadLameMaker.woodStock=BreadLameMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BreadLameMaker.leatherStock=BreadLameMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BreadLameMaker.silverStock=BreadLameMaker.silverStock-d.silverCost*qty end; if d.goldCost then BreadLameMaker.goldStock=BreadLameMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BreadLameMaker.jewelStock=BreadLameMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BreadLameMaker.pearlStock=BreadLameMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BreadLameMaker.maker then t=math.max(1,t-math.floor(BreadLameMaker.maker.skill/13)) end; table.insert(BreadLameMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BreadLameMaker.completeMaking(m) local q=1.0+(BreadLameMaker.getQualityBonus()/100); if BreadLameMaker.maker then q=q+(BreadLameMaker.maker.skill/140) end; q=math.min(2.5,q); BreadLameMaker.productStock[m.productType]=(BreadLameMaker.productStock[m.productType] or 0)+m.quantity; BreadLameMaker.totalProducts=BreadLameMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BreadLameMaker.maker then BreadLameMaker.maker.itemsMade=BreadLameMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BreadLameMaker.maker.skill=math.min(100,BreadLameMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezilo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function BreadLameMaker.update(dt) if not _G.state then return end; BreadLameMaker.dayTimer=BreadLameMaker.dayTimer+dt; if BreadLameMaker.dayTimer>=30 then BreadLameMaker.dayTimer=0; for i=#BreadLameMaker.activeMaking,1,-1 do local m=BreadLameMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BreadLameMaker.completeMaking(m); table.remove(BreadLameMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BreadLameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BreadLameMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BreadLameMaker.getStats() return {ironStock=BreadLameMaker.ironStock,bronzeStock=BreadLameMaker.bronzeStock,woodStock=BreadLameMaker.woodStock,leatherStock=BreadLameMaker.leatherStock,silverStock=BreadLameMaker.silverStock,goldStock=BreadLameMaker.goldStock,jewelStock=BreadLameMaker.jewelStock,pearlStock=BreadLameMaker.pearlStock,productStock=BreadLameMaker.productStock,numBuildings=#BreadLameMaker.buildings,hasMaker=BreadLameMaker.maker~=nil,makerName=BreadLameMaker.maker and BreadLameMaker.maker.name or "—",makerSkill=BreadLameMaker.maker and BreadLameMaker.maker.skill or 0,activeMaking=#BreadLameMaker.activeMaking,totalProducts=BreadLameMaker.totalProducts} end
return BreadLameMaker
